namespace FinalAnswer.Tests {
 public sealed class JavaIntegrationTests {
  static string Artifacts=>Path.GetFullPath("Artifacts");GameManager app;
  IEnumerator Until(Func<bool> condition,string reason,float seconds=20){float start=Time.realtimeSinceStartup;while(!condition()){Assert.Less(Time.realtimeSinceStartup-start,seconds,reason);yield return null;}}
  IEnumerator Scene(){yield return UnityEngine.SceneManagement.SceneManager.LoadSceneAsync("TheLastCommand");yield return null;app=GameManager.Instance;yield return Until(()=>app&&app.Machine&&app.Machine.Ready,"Scene initialization");Directory.CreateDirectory(Artifacts);}
  [UnityTearDown]public IEnumerator Cleanup(){if(GameManager.Instance)UnityEngine.Object.Destroy(GameManager.Instance.gameObject);yield return null;}
  [UnityTest,Category("Integration")]public IEnumerator JavaAuthorityAllTaskPresentationsAndTwentyCorrectAnswers(){yield return Scene();var connect=app.Rooms.Development("http://127.0.0.1:18096");yield return Until(()=>connect.IsCompleted,"HTTP dev room");Assert.IsFalse(connect.IsFaulted,connect.Exception?.ToString());yield return Until(()=>app.Network.Authenticated,"WebSocket AUTH");app.StartGame();yield return Until(()=>app.Snapshots.Current.Obj("lastCommand").Obj("testRound").S("status")=="PLAYING"&&!app.Snapshots.Current.Obj("lastCommand").Obj("testRound").B("waitingForTerminals"),"Terminal ready barrier");
   string[] families={"MATH","NUMBER_SEQUENCE","COMPARISON","FORBIDDEN","ODD_SYMBOL","DECIPHER","POSITION","BUTTON","CIRCUIT","LEVER_SEQUENCE","PRESSURE","RADIO","FAULTY_GAUGE","LEVER","ADJUSTER","HATCH","COLOR","ENTER_CODE","ANIMAL","SYMBOL","REVERSE","SHUTDOWN","NUMBER_MEMORY","ANIMAL_MEMORY","LIGHT_MEMORY","FIND_CHANGE","TIMING","SILENCE","FALSE_COMMAND","DELAYED_EXECUTION"};var presented=new JArray();
   foreach(var family in families){string previous=Round.S("taskId");app.Action("CODE_PANEL","PREVIEW_TASK",family);yield return Until(()=>Round.S("taskId")!=previous,"Preview "+family);yield return new WaitForSecondsRealtime(.5f);Assert.IsTrue(app.Machine.Screen.Built);Assert.AreEqual(family,Round.S("taskType"));presented.Add(family);if(family=="CIRCUIT"||family=="FALSE_COMMAND"){FrameCapture.Write(app.Machine.CameraRig.Camera,Path.Combine(Artifacts,family+".png"));yield return new WaitForSecondsRealtime(.2f);}}
   app.Action("CODE_PANEL","PREVIEW_TASK","MATH");yield return Until(()=>Round.S("taskType")=="MATH","MATH task");yield return new WaitForSecondsRealtime(.4f);for(int i=0;i<9;i++)app.Machine.Touch("KEY","9");app.Machine.Touch("CONFIRM");yield return Until(()=>Round.S("feedback")=="WRONG COMMAND","Authoritative wrong feedback");Assert.AreEqual(0,Round.L("step"));string wrongTask=Round.S("taskId");yield return Until(()=>Round.S("taskId")!=wrongTask,"Comparable replacement task");Assert.AreEqual("MATH",Round.S("taskType"));
   for(int score=0;score<20;score++){yield return Until(()=>Round.L("nextAt")==0&&app.Clock.Now>=Round.L("readyAt"),"Answer readiness");int answer=new Expression(Round.S("instruction")).Evaluate();foreach(char c in answer.ToString())app.Machine.Touch("KEY",c.ToString());Assert.AreEqual(score,Round.L("step"),"Local digits must not score");app.Machine.Touch("CONFIRM");int expected=score+1;yield return Until(()=>Round.L("step")==expected,"Server correct answer "+expected);if(expected<20)yield return Until(()=>Round.L("nextAt")==0,"Next task");}
   Assert.AreEqual("WON",Round.S("status"));Assert.AreEqual(app.Rooms.SelfId,Round.S("winner"));yield return new WaitForSecondsRealtime(1);FrameCapture.Write(app.Machine.CameraRig.Camera,Path.Combine(Artifacts,"victory.png"));yield return new WaitForSecondsRealtime(.5f);File.WriteAllText(Path.Combine(Artifacts,"java-integration.json"),new JObject{{"connected",true},{"wrongAnswerDidNotScore",true},{"replacementSameFamily",true},{"presentedFamilies",presented},{"validatedCorrectAnswers",20},{"serverWinnerConfirmed",true},{"protocolVersion",app.Snapshots.Current.L("protocolVersion")}}.ToString());
  }
  [UnityTest,Category("Integration")]public IEnumerator WorldScreenPointerDownProjectsImmediatelyAndDoesNotRepeatOnRelease(){yield return Scene();var connect=app.Rooms.Development("http://127.0.0.1:18096");yield return Until(()=>connect.IsCompleted,"HTTP dev room");Assert.IsFalse(connect.IsFaulted);yield return Until(()=>app.Network.Authenticated,"Host auth");app.StartGame();yield return Until(()=>Round!=null&&Round.S("status")=="PLAYING"&&!Round.B("waitingForTerminals"),"Terminal ready");string old=Round.S("taskId");app.Action("CODE_PANEL","PREVIEW_TASK","MATH");yield return Until(()=>Round.S("taskId")!=old&&Round.S("taskType")=="MATH","Numeric task");yield return new WaitForSecondsRealtime(.4f);app.Machine.FocusCurrent();yield return new WaitForSecondsRealtime(.8f);Canvas.ForceUpdateCanvases();var key=app.Machine.Screen.GetComponentsInChildren<ImmediatePress>().First();var rect=(RectTransform)key.transform;var point=app.Machine.CameraRig.Camera.WorldToScreenPoint(rect.TransformPoint(rect.rect.center));var data=new PointerEventData(EventSystem.current){position=new Vector2(point.x,point.y),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();app.Machine.Screen.Surface.GetComponent<GraphicRaycaster>().Raycast(data,hits);Assert.IsTrue(hits.Any(x=>x.gameObject==key.gameObject),"The visible 3D keyboard must receive pointer rays through its bezel");ExecuteEvents.Execute(key.gameObject,data,ExecuteEvents.pointerDownHandler);Assert.AreEqual("7",app.Numbers.Value,"Local preview should update before a server frame");Assert.AreEqual("",Round.Obj("touchscreen").S("input"));ExecuteEvents.Execute(key.gameObject,data,ExecuteEvents.pointerUpHandler);ExecuteEvents.Execute(key.gameObject,data,ExecuteEvents.pointerClickHandler);Assert.AreEqual("7",app.Numbers.Value,"Release/click must not type a second digit");yield return Until(()=>Round.Obj("touchscreen").S("input")=="7","Authoritative key acknowledgement");Assert.AreEqual(0,Round.L("step"));app.Action("CODE_PANEL","PREVIEW_TASK","LIGHT_MEMORY");yield return Until(()=>Round.S("taskType")=="LIGHT_MEMORY","Memory task");yield return null;var memoryButton=System.Array.Find(app.Machine.Mechanisms,x=>x.Id=="SMALL_BUTTON_1");Assert.IsFalse(memoryButton.Available,"Memory controls must stay locked during the presentation");yield return Until(()=>memoryButton.Available,"Memory input opens at the authoritative reveal timestamp",8);File.WriteAllText(Path.Combine(Artifacts,"world-screen-input.json"),new JObject{{"worldRaycast",true},{"immediatePointerDown",true},{"noRepeatOnRelease",true},{"serverAcknowledged",true},{"noLocalScoring",true},{"memoryPresentationInputGate",true}}.ToString());}
  JObject Round=>app.Snapshots.Current.Obj("lastCommand").Obj("testRound");
  [UnityTest,Category("BrowserIntegration")]public IEnumerator ProductionRoomWithTwoUnmodifiedBrowserControllers(){yield return Scene();var create=app.Rooms.Create("http://127.0.0.1:18096","Unity browser integration",8);yield return Until(()=>create.IsCompleted,"Create production room");Assert.IsFalse(create.IsFaulted);yield return Until(()=>app.Network.Authenticated,"Host AUTH");File.WriteAllText(Path.Combine(Artifacts,"browser-room.json"),new JObject{{"code",app.Rooms.Code},{"url",app.Rooms.BaseUrl}}.ToString());yield return Until(()=>app.Players.Players.Count==2&&app.Players.Players[0].Online&&app.Players.Players[1].Online,"Two browser phones",90);app.StartGame();yield return Until(()=>Round!=null&&Round.S("status")=="PLAYING"&&!Round.B("waitingForTerminals"),"Production ready barrier",30);Assert.IsTrue(app.Snapshots.Current.Obj("lastCommand").B("development")==false);Assert.AreEqual(0,Round.L("step"));File.WriteAllText(Path.Combine(Artifacts,"browser-unity-result.json"),new JObject{{"players",2},{"productionSession",true},{"hostTerminalReady",true},{"serverAuthority",true}}.ToString());yield return new WaitForSecondsRealtime(2);}
  sealed class Expression {readonly string s;int i;public Expression(string input){s=input.Split('=')[0].Replace("×","*").Replace("÷","/").Replace("−","-").Replace(" ","");}public int Evaluate()=>Sum();int Sum(){int x=Product();while(i<s.Length&&(s[i]=='+'||s[i]=='-')){char op=s[i++];int y=Product();x=op=='+'?x+y:x-y;}return x;}int Product(){int x=Atom();while(i<s.Length&&(s[i]=='*'||s[i]=='/')){char op=s[i++];int y=Atom();x=op=='*'?x*y:x/y;}return x;}int Atom(){if(s[i]=='('){i++;int x=Sum();Assert.AreEqual(')',s[i++]);return x;}int start=i;while(i<s.Length&&char.IsDigit(s[i]))i++;return int.Parse(s.Substring(start,i-start));}}
 }
}
